namespace Payments;

/// <summary>Abstracts the external payment provider (Stripe, Braintree, etc.).</summary>
public interface IPaymentProvider
{
    Task<string> CreateChargeAsync(string cardToken, decimal amount, CancellationToken ct = default);
    Task<string> CreateRefundAsync(string chargeId, CancellationToken ct = default);
}

public sealed class PaymentGateway
{
    private readonly IPaymentProvider _provider;

    public PaymentGateway(IPaymentProvider provider)
    {
        _provider = provider ?? throw new ArgumentNullException(nameof(provider));
    }

    public async Task<ChargeResult> ChargeAsync(string cardToken, decimal amount, CancellationToken ct = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(cardToken);

        if (amount <= 0)
            throw new ArgumentOutOfRangeException(nameof(amount), "Charge amount must be positive.");

        if (amount > 999_999.99m)
            throw new ArgumentOutOfRangeException(nameof(amount), "Charge amount exceeds maximum allowed.");

        try
        {
            var chargeId = await _provider.CreateChargeAsync(cardToken, amount, ct);
            return new ChargeResult(chargeId, Success: true);
        }
        catch (OperationCanceledException)
        {
            throw;
        }
        catch (Exception)
        {
            return new ChargeResult(string.Empty, Success: false);
        }
    }

    public async Task<RefundResult> RefundAsync(string chargeId, CancellationToken ct = default)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(chargeId);

        try
        {
            var refundId = await _provider.CreateRefundAsync(chargeId, ct);
            return new RefundResult(refundId, Success: true);
        }
        catch (OperationCanceledException)
        {
            throw;
        }
        catch (Exception)
        {
            return new RefundResult(string.Empty, Success: false);
        }
    }

    public WebhookResult ProcessWebhook(string eventType, string payload)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(eventType);
        ArgumentException.ThrowIfNullOrWhiteSpace(payload);

        return eventType switch
        {
            "charge.succeeded" => new WebhookResult(WebhookStatus.Processed, "Charge confirmed"),
            "charge.failed" => new WebhookResult(WebhookStatus.Processed, "Charge failed"),
            "refund.created" => new WebhookResult(WebhookStatus.Processed, "Refund initiated"),
            _ => new WebhookResult(WebhookStatus.Ignored, $"Unhandled event: {eventType}"),
        };
    }
}

public record ChargeResult(string ChargeId, bool Success);
public record RefundResult(string RefundId, bool Success);
public record WebhookResult(WebhookStatus Status, string Message);

public enum WebhookStatus
{
    Processed,
    Ignored,
}

