namespace Payments.Tests;

/// <summary>In-memory fake that records calls and allows configuring failures.</summary>
internal sealed class FakePaymentProvider : IPaymentProvider
{
    private readonly Queue<Func<Task<string>>> _chargeResponses = new();
    private readonly Queue<Func<Task<string>>> _refundResponses = new();

    public int ChargeCallCount { get; private set; }
    public int RefundCallCount { get; private set; }

    public string? LastCardToken { get; private set; }
    public decimal? LastAmount { get; private set; }
    public string? LastChargeId { get; private set; }

    public void EnqueueChargeResult(string chargeId) =>
        _chargeResponses.Enqueue(() => Task.FromResult(chargeId));

    public void EnqueueChargeFailure(Exception ex) =>
        _chargeResponses.Enqueue(() => Task.FromException<string>(ex));

    public void EnqueueRefundResult(string refundId) =>
        _refundResponses.Enqueue(() => Task.FromResult(refundId));

    public void EnqueueRefundFailure(Exception ex) =>
        _refundResponses.Enqueue(() => Task.FromException<string>(ex));

    public Task<string> CreateChargeAsync(string cardToken, decimal amount, CancellationToken ct = default)
    {
        ct.ThrowIfCancellationRequested();
        ChargeCallCount++;
        LastCardToken = cardToken;
        LastAmount = amount;
        return _chargeResponses.Count > 0
            ? _chargeResponses.Dequeue()()
            : Task.FromResult($"ch_{Guid.NewGuid():N}");
    }

    public Task<string> CreateRefundAsync(string chargeId, CancellationToken ct = default)
    {
        ct.ThrowIfCancellationRequested();
        RefundCallCount++;
