namespace Payments.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private readonly FakePaymentProvider _provider;
    private readonly PaymentGateway _gateway;

    public PaymentGatewayTests()
    {
        _provider = new FakePaymentProvider();
        _gateway = new PaymentGateway(_provider);
    }

    // ──────────────────────────────────────────────
    //  Constructor validation
    // ──────────────────────────────────────────────

    [TestMethod]
    public void Ctor_NullProvider_ThrowsArgumentNullException()
    {
        var ex = Assert.ThrowsExactly<ArgumentNullException>(() => new PaymentGateway(null!));
        Assert.AreEqual("provider", ex.ParamName);
    }

    // ──────────────────────────────────────────────
    //  ChargeAsync – happy path
    // ──────────────────────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ValidInput_ReturnsSuccessWithChargeId()
    {
        _provider.EnqueueChargeResult("ch_abc123");

        var result = await _gateway.ChargeAsync("tok_visa", 49.99m);

        Assert.IsTrue(result.Success);
        Assert.AreEqual("ch_abc123", result.ChargeId);
        Assert.AreEqual(1, _provider.ChargeCallCount);
    }

    [TestMethod]
    public async Task ChargeAsync_ValidInput_PassesTokenAndAmountToProvider()
    {
        await _gateway.ChargeAsync("tok_mastercard", 100m);

        Assert.AreEqual("tok_mastercard", _provider.LastCardToken);
        Assert.AreEqual(100m, _provider.LastAmount);
    }

    [TestMethod]
    [DataRow(0.01, DisplayName = "Minimum charge")]
    [DataRow(999_999.99, DisplayName = "Maximum charge")]
    [DataRow(50.00, DisplayName = "Typical charge")]
    public async Task ChargeAsync_BoundaryAmounts_Succeeds(double amount)
    {
        var result = await _gateway.ChargeAsync("tok_visa", (decimal)amount);

        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.ChargeId);
    }

    // ──────────────────────────────────────────────
    //  ChargeAsync – input validation
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(null, DisplayName = "Null token")]
    [DataRow("", DisplayName = "Empty token")]
    [DataRow("   ", DisplayName = "Whitespace token")]
    public async Task ChargeAsync_InvalidCardToken_ThrowsArgumentException(string? token)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(token!, 10m));
    }

    [TestMethod]
    [DataRow(0, DisplayName = "Zero amount")]
    [DataRow(-1, DisplayName = "Negative amount")]
    [DataRow(-0.01, DisplayName = "Small negative")]
    public async Task ChargeAsync_NonPositiveAmount_ThrowsArgumentOutOfRange(double amount)
    {
        await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_visa", (decimal)amount));
    }

    [TestMethod]
    public async Task ChargeAsync_ExceedsMaxAmount_ThrowsArgumentOutOfRange()
    {
        await Assert.ThrowsExactlyAsync<ArgumentOutOfRangeException>(
            async () => await _gateway.ChargeAsync("tok_visa", 1_000_000m));
    }

    // ──────────────────────────────────────────────
    //  ChargeAsync – provider failure
    // ──────────────────────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_ProviderThrows_ReturnsFailureResult()
    {
        _provider.EnqueueChargeFailure(new InvalidOperationException("Network timeout"));

        var result = await _gateway.ChargeAsync("tok_visa", 25m);

        Assert.IsFalse(result.Success);
        Assert.AreEqual(string.Empty, result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_ProviderThrowsMultipleTypes_AllReturnFailure()
    {
        _provider.EnqueueChargeFailure(new TimeoutException());
        _provider.EnqueueChargeFailure(new HttpRequestException());

        var r1 = await _gateway.ChargeAsync("tok_visa", 10m);
        var r2 = await _gateway.ChargeAsync("tok_visa", 20m);

        Assert.IsFalse(r1.Success);
        Assert.IsFalse(r2.Success);
    }

    // ──────────────────────────────────────────────
    //  ChargeAsync – cancellation
    // ──────────────────────────────────────────────

    [TestMethod]
    public async Task ChargeAsync_CancellationRequested_ThrowsOperationCanceled()
    {
        using var cts = new CancellationTokenSource();
        cts.Cancel();

        await Assert.ThrowsExactlyAsync<OperationCanceledException>(
            async () => await _gateway.ChargeAsync("tok_visa", 10m, cts.Token));
    }

    // ──────────────────────────────────────────────
    //  RefundAsync – happy path
    // ──────────────────────────────────────────────

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessWithRefundId()
    {
        _provider.EnqueueRefundResult("re_xyz789");

        var result = await _gateway.RefundAsync("ch_abc123");

        Assert.IsTrue(result.Success);
        Assert.AreEqual("re_xyz789", result.RefundId);
        Assert.AreEqual(1, _provider.RefundCallCount);
    }

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_PassesChargeIdToProvider()
    {
        await _gateway.RefundAsync("ch_original");

        Assert.AreEqual("ch_original", _provider.LastChargeId);
    }

    // ──────────────────────────────────────────────
    //  RefundAsync – input validation
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(null, DisplayName = "Null chargeId")]
    [DataRow("", DisplayName = "Empty chargeId")]
    [DataRow("   ", DisplayName = "Whitespace chargeId")]
    public async Task RefundAsync_InvalidChargeId_ThrowsArgumentException(string? chargeId)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(chargeId!));
    }

    // ──────────────────────────────────────────────
    //  RefundAsync – provider failure
    // ──────────────────────────────────────────────

    [TestMethod]
    public async Task RefundAsync_ProviderThrows_ReturnsFailureResult()
    {
        _provider.EnqueueRefundFailure(new InvalidOperationException("Charge not found"));

        var result = await _gateway.RefundAsync("ch_nonexistent");

        Assert.IsFalse(result.Success);
        Assert.AreEqual(string.Empty, result.RefundId);
    }

    // ──────────────────────────────────────────────
    //  RefundAsync – cancellation
    // ──────────────────────────────────────────────

    [TestMethod]
    public async Task RefundAsync_CancellationRequested_ThrowsOperationCanceled()
    {
        using var cts = new CancellationTokenSource();
        cts.Cancel();

        await Assert.ThrowsExactlyAsync<OperationCanceledException>(
            async () => await _gateway.RefundAsync("ch_abc123", cts.Token));
    }

    // ──────────────────────────────────────────────
    //  ProcessWebhook – known event types
    // ──────────────────────────────────────────────

    [TestMethod]
    [DynamicData(nameof(KnownWebhookEvents))]
    public void ProcessWebhook_KnownEvent_ReturnsProcessed(string eventType, string expectedMessage)
    {
        var result = _gateway.ProcessWebhook(eventType, """{"id":"evt_1"}""");

        Assert.AreEqual(WebhookStatus.Processed, result.Status);
        Assert.AreEqual(expectedMessage, result.Message);
    }

    public static IEnumerable<(string eventType, string expectedMessage)> KnownWebhookEvents =>
    [
        ("charge.succeeded", "Charge confirmed"),
        ("charge.failed", "Charge failed"),
        ("refund.created", "Refund initiated"),
    ];

    // ──────────────────────────────────────────────
    //  ProcessWebhook – unknown event
    // ──────────────────────────────────────────────

    [TestMethod]
    public void ProcessWebhook_UnknownEvent_ReturnsIgnored()
    {
        var result = _gateway.ProcessWebhook("invoice.paid", """{"id":"evt_2"}""");

        Assert.AreEqual(WebhookStatus.Ignored, result.Status);
        Assert.Contains("invoice.paid", result.Message);
    }

    // ──────────────────────────────────────────────
    //  ProcessWebhook – input validation
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(null, "payload", DisplayName = "Null eventType")]
    [DataRow("", "payload", DisplayName = "Empty eventType")]
    [DataRow("charge.succeeded", null, DisplayName = "Null payload")]
    [DataRow("charge.succeeded", "", DisplayName = "Empty payload")]
    public void ProcessWebhook_InvalidInput_ThrowsArgumentException(string? eventType, string? payload)
    {
        Assert.ThrowsExactly<ArgumentException>(
            () => _gateway.ProcessWebhook(eventType!, payload!));
    }

    // ──────────────────────────────────────────────
    //  End-to-end: charge then refund
    // ──────────────────────────────────────────────

    [TestMethod]
    public async Task ChargeThenRefund_FullFlow_BothSucceed()
    {
        _provider.EnqueueChargeResult("ch_flow");
        _provider.EnqueueRefundResult("re_flow");

        var charge = await _gateway.ChargeAsync("tok_visa", 75m);
        var refund = await _gateway.RefundAsync(charge.ChargeId);

        Assert.IsTrue(charge.Success);
        Assert.IsTrue(refund.Success);
        Assert.AreEqual("ch_flow", _provider.LastChargeId);
    }
}

